import{_ as a,o as e,c as s,ag as l}from"./chunks/framework.C9sp7nFj.js";const b=JSON.parse('{"title":"celestial-architect（营造师）","description":"","frontmatter":{},"headers":[],"relativePath":"AI/short-video/celestial-architect.md","filePath":"AI/short-video/celestial-architect.md"}'),i={name:"AI/short-video/celestial-architect.md"};function n(d,t,r,h,c,o){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="celestial-architect-营造师" tabindex="-1">celestial-architect（营造师） <a class="header-anchor" href="#celestial-architect-营造师" aria-label="Permalink to &quot;celestial-architect（营造师）&quot;">​</a></h1><p><a href="https://github.com/irenerachel/celestial-architect-skill" target="_blank" rel="noreferrer">celestial-architect-skill</a> 是一套面向 AI Agent 的中文 Skill：把一张参考图、一句古诗或一个建筑关键词，营造成可直接用于 AI 生图的中式巨构、云上白玉京与仙侠场景提示词。</p><p>以《营造法式》《清式营造则例》中的建筑正名为骨架，结合郭熙三远法、样式雷图学与电影概念设计方法，写出形制准确、尺度宏大、构图清晰的中式幻想建筑提示词。</p><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><p>说以下关键词即可触发：</p><ul><li>「营造师」「白玉京」「中式巨构」「中式赛博」「天上白玉京」</li><li>给一张图，要求「参考构图/角度出中式巨构提示词」</li><li>给古诗句或建筑关键词（亭/台/楼/阁/桥/檐/栈道等）</li><li>给修仙门派场所或局部场景词（炼丹房/藏书阁/洞府秘境/园林/檐角一隅/漏窗等）</li></ul><p><strong>不适用</strong>：通用图片反推、视觉 DNA 裂变、一图生模板、其他风格的提示词生成。</p><h2 id="两条风格路线" tabindex="-1">两条风格路线 <a class="header-anchor" href="#两条风格路线" aria-label="Permalink to &quot;两条风格路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路线</th><th>气质</th><th>光法</th></tr></thead><tbody><tr><td><strong>A 路｜云上白玉京</strong>（默认）</td><td>少赛博，多仙气。科技作「不可见的承重」</td><td>暖金自然光（晨金/夕金/体积雾）；夜景用月银 + 宫灯暖点</td></tr><tr><td><strong>B 路｜宫城蓝线图</strong></td><td>冷光只描结构，像「未建成/正在显影」</td><td>钴蓝全息线框叠在宫墙、斗栱上；朱墙金瓦仍在</td></tr></tbody></table><p>文学锚点：李白「天上白玉京，十二楼五城」——仙都，不是夜店长安。</p><h2 id="三个输入入口" tabindex="-1">三个输入入口 <a class="header-anchor" href="#三个输入入口" aria-label="Permalink to &quot;三个输入入口&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>入口一：识图 → 构图基因移植（只移植机位与构图，元素转译为中式）</span></span>
<span class="line"><span>入口二：诗句 → 意象四抽（构件名词 / 动词空间 / 数量尺度 / 时间气象）</span></span>
<span class="line"><span>入口三：关键词 → 按景别路由（宏观巨构 / 门派场所 / 局部特写）</span></span></code></pre></div><p>识图转译示例：</p><table tabindex="0"><thead><tr><th>原图元素</th><th>中式转译</th></tr></thead><tbody><tr><td>哥特尖塔 / 教堂钟楼</td><td>密檐塔 / 阙楼 / 重檐楼阁</td></tr><tr><td>玻璃幕墙 / 现代高层</td><td>逐层收分的重檐楼身 + 隔扇窗</td></tr><tr><td>摩天楼天际线</td><td>十二楼五城纵深宫城群</td></tr></tbody></table><h2 id="默认输出" tabindex="-1">默认输出 <a class="header-anchor" href="#默认输出" aria-label="Permalink to &quot;默认输出&quot;">​</a></h2><ul><li>单路线，同一场景，<strong>3 组互补视角</strong>（密 / 均 / 疏三档递减）</li><li>每组先中文提示词，再英文提示词，两个独立代码块</li><li>画幅默认 9:16 立轴；平远建立镜头可 16:9；藻井大样可 1:1</li><li>提示词全部输出后，可复制到 Midjourney / 即梦等平台出图，或存档到本地 markdown</li></ul><p>输出示例结构：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 第 1 组｜{诗意标题}（A 路 · 高远 · 9:16）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{中文提示词}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{英文提示词}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span></code></pre></div><h2 id="三条铁律" tabindex="-1">三条铁律 <a class="header-anchor" href="#三条铁律" aria-label="Permalink to &quot;三条铁律&quot;">​</a></h2><ol><li><strong>构件写死，术语用正名</strong>：禁止只写「中式建筑」。必须写到形制颗粒度——庑殿/歇山/攒尖、几踩斗栱、须弥座、鸱吻脊兽等</li><li><strong>画面必有尺度感</strong>：远景巨构带比例尺（默认一人背影占画面下沿一角）；无人物时用飞鸟/舟楫/宫灯等替代锚</li><li><strong>暖光打建筑，冷光只描边</strong>：冷光铺满就滑向霓虹街</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>Skill 自带四份 reference，写提示词时按需查：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>references/构件语汇库.md</code></td><td>大木作/瓦石/装修/彩画正名、高冲击力词条、真实母本建筑</td></tr><tr><td><code>references/机位与图学.md</code></td><td>三远法、借景机位库、样式雷图学五样</td></tr><tr><td><code>references/场景与室境.md</code></td><td>修仙场所谱、园林场景、局部特写谱</td></tr><tr><td><code>references/黄金样例.md</code></td><td>五组成稿示例，方向与颗粒度参照</td></tr></tbody></table><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>从仓库下载 <a href="https://github.com/irenerachel/celestial-architect-skill/blob/main/%E8%90%A5%E9%80%A0%E5%B8%88.skill" target="_blank" rel="noreferrer"><code>营造师.skill</code></a>，解压后将技能目录命名为 <code>celestial-architect</code>，放进当前 Agent 的 Skills 目录。常见路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/skills/celestial-architect/   # Claude Code</span></span>
<span class="line"><span>~/.codex/skills/celestial-architect/    # Codex</span></span>
<span class="line"><span># 其他支持 Skill 的 Agent，目录结构类似</span></span></code></pre></div><p>安装后目录结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>celestial-architect/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>└── references/</span></span>
<span class="line"><span>    ├── 场景与室境.md</span></span>
<span class="line"><span>    ├── 构件语汇库.md</span></span>
<span class="line"><span>    ├── 机位与图学.md</span></span>
<span class="line"><span>    └── 黄金样例.md</span></span></code></pre></div><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>安装后在 Agent 对话里直接说意图即可，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调用 celestial-architect，参考这张图的构图和视角，营造成云上白玉京。人物使用古装小背影。</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调用 celestial-architect，把&quot;危楼高百尺，手可摘星辰&quot;营造成天上白玉京。人物使用古装小背影。</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调用 celestial-architect，营造一座悬在云壑之上的藏书阁，走 A 路，无人物。</span></span></code></pre></div><p>Agent 负责生成提示词，<strong>不负责出图</strong>。提示词全部输出后，复制到外部生图平台使用：</p><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><strong>Midjourney</strong></td><td>仓库案例多用 MJ V8 测试，复杂巨构效果较好</td></tr><tr><td><strong>即梦</strong></td><td>国内访问方便，支持参考图垫图</td></tr><tr><td><strong>nano-banana 等</strong></td><td>按平台习惯粘贴中文或英文提示词</td></tr></tbody></table><p>Skill 默认不会自动出图，也不会消耗生图额度。需要存档时，可将提示词保存到本地 markdown 文件。</p><h2 id="与-shuohao-skills-的关系" tabindex="-1">与 shuohao-skills 的关系 <a class="header-anchor" href="#与-shuohao-skills-的关系" aria-label="Permalink to &quot;与 shuohao-skills 的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>shuohao-skills</th><th>celestial-architect</th></tr></thead><tbody><tr><td>定位</td><td>短剧制作管线（大纲→分镜→投产包）</td><td>单张概念图 / 场景图的提示词营造</td></tr><tr><td>产出</td><td>json + md + html 报告 + 分镜 png</td><td>中英双语提示词（复制到外部平台出图）</td></tr><tr><td>场景</td><td>整剧工业化生产</td><td>美术设定、封面、氛围图、分镜参考</td></tr></tbody></table><p>短剧管线里的 <code>novel-art</code> 出场景设定图时，可以用营造师生成的提示词作为风格参考或垫图输入。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li>仓库：<a href="https://github.com/irenerachel/celestial-architect-skill" target="_blank" rel="noreferrer">github.com/irenerachel/celestial-architect-skill</a></li><li><a href="./../skill.html">Skill 技能文件</a></li><li><a href="./shuohao-skills.html">shuohao-skills 短剧管线</a></li></ul>`,41)])])}const g=a(i,[["render",n]]);export{b as __pageData,g as default};
